import set = require( './index' );


// TESTS //

// The function returns any...
{
	set( { 'a': { 'b': 1 } }, [ 'a', 'b' ], 99 ); // $ExpectType any
	set( [ 1, 2, 3 ], [ '0' ], 99 ); // $ExpectType any
	set( { 'a': 1 }, [], { 'b': 2 } ); // $ExpectType any
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	set(); // $ExpectError
	set( { 'a': 1 } ); // $ExpectError
	set( { 'a': 1 }, [ 'a' ] ); // $ExpectError
	set( { 'a': 1 }, [ 'a' ], 99, true ); // $ExpectError
}
